def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 assert Path('/media/zhuyupei/SanStand').is_mount()
 src=F/'view_source/source.json';pr=F/'view_source/original_proposals.json';m=json.loads(src.read_text());p=json.loads(pr.read_text());assert sha(src)==p['source_json_sha256'];assert all(x['match']for x in m['source_hashes'].values());assert sha(F/'view_source/source.npz')==m['source_npz_sha256']
 bounds=[]
 for i,g in enumerate(m['arguments']['gaps']):
  old=np.array(g['initial_camera_origin_base_m'])-g['target_center_base_m'];direction=old/np.linalg.norm(old);jaw=np.array(g['jaw_axis_base']);height=g['object_height_m'];noise=m['arguments']['depth_uncertainty_m']
