 files=[src,pr,F/'view_source/source.npz',F/'view_source/model.urdf',Path(m['audit_path']),W/'src/alicia_grasp_modes/src/alicia_grasp_modes/observe_return_visual.py',W/'src/alicia_grasp_modes/scripts/mode_aware_remote_grasp6d.py',W/'src/alicia_grasp_modes/src/alicia_grasp_modes/reachable_observation_views.py',W/'src/alicia_grasp_modes/src/alicia_grasp_modes/arrival_dense_identity.py',W/'src/alicia_grasp_modes/src/alicia_grasp_modes/observation_arrival_confirmation.py',Path(__file__)]
 report=dict(scope='Independent read-only synthesis of completed original-source proposal replay and mathematical lower bound; original solve not rerun.',passed=True,no_motion=True,no_ros_connections=True,all_six_original_source_hashes_match=m['source_hashes'],source_sha256={str(q):sha(q)for q in files},derivation=dict(definitions='u0=(old_camera-center)/norm; j=unit jaw axis; s=missing sign; h=measured height; sigma=original depth uncertainty.',original_gate='h*max(0,s*j.u) - h*max(0,s*j.u0) > sigma+1e-9 AND s*j.(camera-center) > half_width+1e-9',angular_bound='angle(u,u0) > acos(s*j.u0)-acos(max(0,s*j.u0)+sigma/h). This is an infimum lower bound ignoring positive numerical reserve and extra whole-body/FOV/CAD/path constraints.',all_old_sides_opposite=all(x['initial_signed_direction_cosine']<0 for x in bounds),minimum_degrees=min(x['minimum_direction_change_degrees_strict']for x in bounds),per_missing_side=bounds),recorded_selected_search=p['recorded_search_summary'],recorded_selected_view=p['recorded_selected_view'],original_four_candidates=p['original_fk_candidates'],original_solver_audit=p['original_fk_audit'],original_orientation_and_radial_controls=p['controls'],conclusions=['All 6 missing-side directions require crossing the old viewing side; no exactly preserved target incidence/azimuth radial view can pass the original information gate.', 'The smallest original feasible endpoint changes target ray by about 38.02 degrees, near the independent 37.43 degree infimum. A visually similar new view is not guaranteed.', 'The recorded planner inspected one of 228 configured endpoint candidates. The first full-path-qualified FK incumbent ends dispatch; no claim that all alternatives were checked or inferior is supported.', 'All four replay proposals passed original endpoint gates. Only the selected historical endpoint has an actual saved full MoveIt path. Alternative full robot collision/path feasibility is not proved by endpoint FK.', 'Changing only ranking cannot establish current RGB identity. All historical appearance/three-frame failures remain failures.'],limitations=['Pose descriptions are geometric proxies, not predictions that whole-mask single-H RGB gates pass.', 'Visibility-aware or face-specific identity would be a new evidence contract, not an unchanged whole-object homography gate. No face crop was granted identity, geometry, motion or freshness authority.'])
 out=F/'view_conflict_receipt.json';assert not out.exists();out.write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(dict(path=str(out),sha256=sha(out),minimum_angle_deg=report['derivation']['minimum_degrees'],candidates=len(report['original_four_candidates']))))
